import{_ as i,c as r,o,j as a,af as n,a as d,t as e}from"./chunks/framework.W5ZyBR1w.js";const _=JSON.parse('{"title":"控制器说明","description":"本章主要讲述 MSST-Net 客户端控制器的类型与适用场景。","frontmatter":{"title":"控制器说明","description":"本章主要讲述 MSST-Net 客户端控制器的类型与适用场景。"},"headers":[],"relativePath":"connect/install/controller.md","filePath":"connect/install/controller.md"}'),p={name:"connect/install/controller.md"},s={id:"frontmatter-title",tabindex:"-1"};function h(l,t,c,u,m,b){return o(),r("div",null,[a("h1",s,[d(e(l.$frontmatter.title)+" ",1),t[0]||(t[0]=a("a",{class:"header-anchor",href:"#frontmatter-title","aria-label":"Permalink to “{{ $frontmatter.title }}”"},"​",-1))]),a("p",null,e(l.$frontmatter.description),1),t[1]||(t[1]=n('<h2 id="控制器的作用" tabindex="-1">控制器的作用 <a class="header-anchor" href="#控制器的作用" aria-label="Permalink to “控制器的作用”">​</a></h2><p>客户端控制器用于管理 <strong>MSST-Net 客户端核心</strong>。</p><p>其主要功能包括：</p><ul><li>配置客户端核心</li><li>管理网络连接</li><li>管理房间</li><li>查看设备状态</li><li>执行接入认证</li></ul><p>控制器本身不负责网络连接功能。</p><hr><h2 id="控制器类型" tabindex="-1">控制器类型 <a class="header-anchor" href="#控制器类型" aria-label="Permalink to “控制器类型”">​</a></h2><p>MSST-Net 当前提供以下控制器实现：</p><table tabindex="0"><thead><tr><th>类型</th><th>平台</th><th>图形界面</th><th>远程管理</th></tr></thead><tbody><tr><td>Tauri</td><td>桌面端</td><td>是</td><td>否</td></tr><tr><td>WebUI</td><td>桌面端 / 服务器</td><td>是（浏览器）</td><td>是</td></tr><tr><td>Compose</td><td>移动端</td><td>是</td><td>否</td></tr></tbody></table><hr><h2 id="tauri-版控制器" tabindex="-1">Tauri 版控制器 <a class="header-anchor" href="#tauri-版控制器" aria-label="Permalink to “Tauri 版控制器”">​</a></h2><p>Tauri 版控制器适用于具备桌面环境的设备。</p><p>特点：</p><ul><li>本地图形界面</li><li>本地运行</li><li>操作完整</li><li>响应速度快</li></ul><p>适用场景：</p><ul><li>Windows</li><li>Linux</li><li>macOS</li></ul><p>推荐给普通桌面用户使用。</p><hr><h2 id="webui-版控制器" tabindex="-1">WebUI 版控制器 <a class="header-anchor" href="#webui-版控制器" aria-label="Permalink to “WebUI 版控制器”">​</a></h2><p>WebUI 版控制器适用于无桌面环境或需要远程管理的设备。</p><p>特点：</p><ul><li>浏览器访问</li><li>支持远程管理</li><li>部署灵活</li><li>不依赖桌面环境</li></ul><p>适用场景：</p><ul><li>服务器</li><li>远程设备</li><li>无图形环境设备</li></ul><p>推荐给服务器用户使用。</p><hr><h2 id="compose-版控制器" tabindex="-1">Compose 版控制器 <a class="header-anchor" href="#compose-版控制器" aria-label="Permalink to “Compose 版控制器”">​</a></h2><p>Compose 版控制器适用于移动端设备。</p><p>特点：</p><ul><li>原生移动端界面</li><li>内置客户端核心</li><li>无需单独安装核心组件</li></ul><p>适用场景：</p><ul><li>Android</li></ul><p>推荐给移动端用户使用。</p><hr><h2 id="如何选择控制器" tabindex="-1">如何选择控制器 <a class="header-anchor" href="#如何选择控制器" aria-label="Permalink to “如何选择控制器”">​</a></h2><p>普通桌面用户：</p><p>建议使用 <strong>Tauri</strong> 版。</p><p>服务器用户：</p><p>建议使用 <strong>WebUI</strong> 版。</p><p>移动端用户：</p><p>建议使用 <strong>Compose</strong> 版。</p><hr><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to “注意事项”">​</a></h2><p>不同控制器的配置数据通常可以互通，但具体行为可能因平台不同而有所差异。</p><p>建议根据设备类型选择最合适的控制器。</p><hr><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><p>完成控制器选择后，请继续：</p><ul><li>安装客户端</li><li>完成接入认证</li></ul><p>详见：</p><ul><li><a href="/connect/install/client">《安装客户端》</a></li><li><a href="/connect/start">《新手教程》</a></li></ul>',51))])}const T=i(p,[["render",h]]);export{_ as __pageData,T as default};
